import Link from "next/link";
import { readFileSync } from "node:fs";
import path from "node:path";
import { ThemeToggle } from "./ThemeToggle";
import { CATEGORIES, CATEGORY, UI } from "@/lib/i18n";
import { href, SITE_NAME, TAGLINE, VIN_URL, type Lang } from "@/lib/site";

// Wordmark path generated by scripts/generate-brand.py, inlined so it needs no web font.
const wm = readFileSync(path.join(process.cwd(), "public/brand/tipmonk-wordmark.svg"), "utf8");
const WM_VIEWBOX = wm.match(/viewBox="([^"]+)"/)?.[1] ?? "0 0 370 95";
const WM_PATH = wm.match(/<path d="([^"]+)"/)?.[1] ?? "";

export function Chrome({ lang, children }: { lang: Lang; children: React.ReactNode }) {
  const t = UI[lang];
  const other: Lang = lang === "ko" ? "en" : "ko";
  return (
    <>
      <a href="#main" className="skip-link">
        {t.skip}
      </a>
      <header className="site-header no-print">
        <div className="wrap header-inner">
          <Link href={href(lang, "/")} className="logo" aria-label={`${SITE_NAME}: ${TAGLINE[lang]}`}>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src="/brand/tipmonk-badge.svg" width={40} height={40} alt="" className="logo-badge" />
            <svg className="logo-word" viewBox={WM_VIEWBOX} aria-hidden="true" focusable="false">
              <path d={WM_PATH} fill="currentColor" />
            </svg>
            <span className="logo-tagline" aria-hidden="true">
              {TAGLINE[lang]}
            </span>
          </Link>
          <nav aria-label="Main" className="header-nav">
            <Link href={href(lang, "/about/")} className="hide-sm">
              {t.about}
            </Link>
            {/* only one label is displayed at a time, so the accessible name matches what's visible */}
            <Link href={href(other, "/")} hrefLang={other} lang={other} className="lang-switch">
              <span className="hide-sm">{t.otherLang}</span>
              <span className="show-sm">{other.toUpperCase()}</span>
            </Link>
            <ThemeToggle />
          </nav>
        </div>
        <nav aria-label={t.categories} className="cat-nav">
          <div className="wrap cat-inner">
            {CATEGORIES.map((c) => (
              <Link key={c} href={href(lang, `/category/${c}/`)}>
                {CATEGORY[c][lang].name}
              </Link>
            ))}
            <Link href={href(lang, "/glossary/")}>{t.glossary}</Link>
          </div>
        </nav>
      </header>
      <main id="main" className="wrap">
        {children}
      </main>
      <footer className="site-footer">
        <div className="wrap">
          <nav aria-label="Footer" className="footer-links no-print">
            <Link href={href(lang, "/about/")}>{t.about}</Link>
            <Link href={href(lang, "/author/inog-kim/")}>{t.author}</Link>
            <Link href={href(lang, "/disclaimer/")}>{t.disclaimer}</Link>
            <Link href={href(lang, "/privacy/")}>{t.privacy}</Link>
            <Link href={href(lang, "/terms/")}>{t.terms}</Link>
            <Link href={href(lang, "/contact/")}>{t.contact}</Link>
            <a href={VIN_URL}>{t.vinTool}</a>
          </nav>
          <p className="small muted footer-note">
            {lang === "ko"
              ? "tipmonk의 모든 글은 공개된 공시와 자료를 바탕으로 한 개인 학습 기록이며, 투자 권유가 아닙니다."
              : "Everything on tipmonk is a personal study of public filings and data. Nothing here is investment advice."}
          </p>
        </div>
      </footer>
    </>
  );
}
